  static String lookup(String text, String langCode) {
    if (langCode == 'en' || text.trim().isEmpty) return text;
    if (translations.containsKey(text) && translations[text]!.containsKey(langCode)) {
      return translations[text]![langCode]!;
    }
    return text;
  }
